namespace sv_8ddb4f7ec9f3435bae2bc36e442fcc5e.Services;

public class WarehouseState
{
    public string SelectedWarehouseId { get; private set; } = "WH-A";
    public string SelectedWarehouseName => Warehouses[SelectedWarehouseId];

    public static IReadOnlyDictionary<string, string> Warehouses { get; } =
        new Dictionary<string, string>
        {
            ["WH-A"] = "Warehouse A",
            ["WH-B"] = "Warehouse B",
            ["WH-C"] = "Warehouse C",
        };

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (SelectedWarehouseId == warehouseId) return;
        SelectedWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_8ddb4f7ec9f3435bae2bc36e442fcc5e.Services;

public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();
    private Timer? _timer;
    private int _subscriberCount;
    private CancellationTokenSource? _cts;

    public int LowStockCount { get; private set; }

    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulates a database query
        return Task.FromResult(_random.Next(0, 16));
    }

    public void StartPolling()
    {
        _subscriberCount++;
        if (_timer is not null) return;

        _cts = new CancellationTokenSource();
        _timer = new Timer(async _ => await PollAsync(), null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
    }

    public void StopPolling()
    {
        _subscriberCount--;
        if (_subscriberCount <= 0)
        {
            _subscriberCount = 0;
            DisposeTimer();
        }
    }

    private async Task PollAsync()
    {
        var count = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
        LowStockCount = count;
        OnAlertCountChanged?.Invoke();
    }

    private void OnWarehouseChanged()
    {
        // When warehouse changes, immediately refresh if polling is active
        if (_timer is not null)
        {
            _ = PollAsync();
        }
    }

    private void DisposeTimer()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        DisposeTimer();
    }
}

