@using sv_8ddb4f7ec9f3435bae2bc36e442fcc5e.Services
@inject WarehouseState Warehouse
@implements IDisposable
@rendermode InteractiveServer

<select class="form-select form-select-sm w-auto" @onchange="OnWarehouseSelected">
    @foreach (var wh in WarehouseState.Warehouses)
    {
        <option value="@wh.Key" selected="@(wh.Key == Warehouse.SelectedWarehouseId)">@wh.Value</option>
    }
</select>

@code {
    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            Warehouse.SetWarehouse(id);
        }
    }

    // Subscribe so this component re-renders if another component changes the warehouse
    protected override void OnInitialized()
    {
        Warehouse.OnChange += HandleChange;
    }

    private void HandleChange() => InvokeAsync(StateHasChanged);

    public void Dispose() => Warehouse.OnChange -= HandleChange;
}

