@page "/dashboard"
@using sv_8ddb4f7ec9f3435bae2bc36e442fcc5e.Services
@inject WarehouseState Warehouse
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-3">
    <div class="card-body">
        <h5 class="card-title">@Warehouse.SelectedWarehouseName</h5>
        <p class="card-text">
            Low-stock alerts:
            <span class="badge bg-warning text-dark fs-5">@AlertService.LowStockCount</span>
        </p>
        <p class="text-muted">Polling every 10 seconds. All subscribed components update together.</p>
    </div>
</div>

@code {
    private Action? _alertHandler;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        _alertHandler = () => InvokeAsync(StateHasChanged);
        _warehouseHandler = () => InvokeAsync(StateHasChanged);

        AlertService.OnAlertCountChanged += _alertHandler;
        Warehouse.OnChange += _warehouseHandler;

        // Start polling when this page becomes visible
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= _alertHandler;
        Warehouse.OnChange -= _warehouseHandler;

        // Stop polling when the user leaves the page
        AlertService.StopPolling();
    }
}

